correctedCode:
#include <stdio.h>
#include <stdlib.h>

int* makeValue() {
    int *heapValue = malloc(sizeof(int));
    *heapValue = 42;
    return heapValue;
}

int main() {
    int *p = makeValue();
    printf("%d\n", *p);
    free(p);
    return 0;
}
